1	import Link from "next/link";
2	import type { ReactNode } from "react";
3	import type { Metadata } from "next";
4	import { db } from "@/lib/db";
5	import { GAME_FAMILIES } from "@/lib/games";
6	import { currentPromo } from "@/lib/promotions";
7	import { firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
8	import { annualDiscountPct } from "@/lib/annual-discount";
9	import { VPS_TERMS, ANNUAL_TERM_MONTHS, termPriceCents } from "@/lib/billing-terms";
10	import { Reveal } from "@/components/marketing/Reveal";
11	import { PricingNav, type NavItem } from "@/components/marketing/PricingNav";
12	import { POPULAR_TLDS } from "@/components/marketing/tlds";
13	import { Section, SectionTitle } from "@/components/marketing/primitives";
14	import { CtaBand } from "@/components/marketing/sections";
15	import { ProductJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
16	import { AmbientField } from "@/components/marketing/AmbientField";
17	import { DeployCard } from "@/components/marketing/DeployCard";
18	import { LogoMarquee } from "@/components/marketing/LogoMarquee";
19	import { ReviewBadges } from "@/components/marketing/ReviewBadges";
20	import { Testimonials } from "@/components/marketing/Testimonials";
21	import { CustomerReviews } from "@/components/marketing/CustomerReviews";
22	import { TermLadder, type TermRung } from "@/components/marketing/TermLadder";
23	import { MailInbox } from "@/components/marketing/showcase/MailInbox";
24	import { DnsManager } from "@/components/marketing/showcase/DnsManager";
25	import { GameControlPanel } from "@/components/marketing/showcase/GameControlPanel";
26	import {
27	  IconCheck,
28	  IconGlobe,
29	  IconShield,
30	  IconBackup,
31	  IconTerminal,
32	  IconNvme,
33	  IconServer,
34	  IconGame,
35	  IconApps,
36	  IconMail,
37	  IconArrow,
38	  IconBolt,
39	} from "@/components/marketing/icons";
40	
41	export const dynamic = "force-dynamic";
42	
43	export const metadata: Metadata = {
44	  title: "Pricing",
45	  description:
46	    "One place to compare every Nxeon product — Cloud VPS, game servers, shared web hosting, business email and domains. Live catalogue prices, monthly billing, no lock-in.",
47	  alternates: { canonical: "/pricing" },
48	};
49	
50	/**
51	 * The ONE money helper for this page. Every price rendered below is passed
52	 * through here straight from a database record (db.plan / db.hostingPlan /
53	 * db.emailPlan / db.gamePlan) — there is not a single hard-coded plan price on
54	 * this page, so a catalogue edit propagates here automatically and can never
55	 * advertise a number checkout won't honour. (Domain TLDs are the one exception
56	 * and are explicitly labelled "indicative" — there is no TLD price table to read
57	 * and the domain search quotes the live, exact figure.)
58	 */
59	function money(cents: number): string {
60	  const v = cents / 100;
61	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
62	}
63	function gb(mb: number): string {
64	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
65	}
66	
67	const NAV: NavItem[] = [
68	  { id: "vps", label: "Cloud VPS", accent: "violet" },
69	  { id: "game-servers", label: "Game Servers", accent: "emerald" },
70	  { id: "hosting", label: "Shared Hosting", accent: "cyan" },
71	  { id: "email", label: "Business Email", accent: "sky" },
72	  { id: "domains", label: "Domains", accent: "violet" },
73	];
74	
75	// Shared "included on every paid plan" trust row — one place, all products.
76	const INCLUDED = [
77	  { icon: <IconGlobe />, label: "Free SSL / IPv4" },
78	  { icon: <IconShield />, label: "DDoS protection" },
79	  { icon: <IconBackup />, label: "Automatic backups" },
80	  { icon: <IconServer />, label: "Free migration" },
81	  { icon: <IconNvme />, label: "NVMe storage" },
82	];
83	
84	const VPS_FEATURES = ["Full root access", "Dedicated IPv4", "NVMe SSD storage", "DDoS protection", "Automatic backups", "One-click reinstall"];
85	const HOSTING_FEATURES = ["Free SSL certificate", "One-click WordPress", "Free site migration", "DDoS protection"];
86	const EMAIL_FEATURES = ["Webmail + IMAP/SMTP", "Spam & virus filtering", "Shared calendars & contacts", "Automatic MX/SPF setup"];
87	
88	const FAQ = [
89	  { q: "How does billing work across products?", a: "Every Nxeon product — VPS, game servers, shared hosting, business email and domains — is prepaid from your wallet balance, monthly by default. VPS also offers optional annual and multi-year terms at a discount: pick the Annual (or longer) term in the deploy wizard to pay once for the whole year up front and save. Whatever term you choose, services auto-renew at exactly that same price — the price you sign up at is the price you renew at — and nothing locks you in: cancel anytime and billing stops at the end of the current period." },
90	  { q: "Is the first month really free?", a: "On shared web hosting, yes — your first month is on us, then the plan renews at exactly the regular monthly price you see (no teaser jump). The free-month offer applies to shared hosting only; VPS, game servers, business email and domains bill their regular price from month one." },
91	  { q: "Which product should I choose?", a: "Use the index at the top: developers who want full control pick a Cloud VPS; communities hosting games pick a game server; anyone who just wants a website online (WordPress, SSL, a control panel) picks shared hosting; teams who only need professional mailboxes pick Business Email; and everyone can register a domain to tie it together." },
92	  { q: "Can I upgrade or downgrade later?", a: "Yes. VPS and game plans resize from the dashboard, hosting and email plans move up or down a tier, and everything stays on the same wallet — no rebuild, no new account." },
93	  { q: "Are the prices shown what I actually pay?", a: "Yes. Every price on this page is read live from the same catalogue the checkout charges from, so the number you see is the number you pay. Domain extensions show an indicative starting price — search a name for the exact live figure." },
94	  { q: "What's included on every plan?", a: "Free SSL and a dedicated IP where applicable, always-on DDoS protection, automatic backups, free migration help, and enterprise NVMe storage — the platform is the same whether you're on the smallest or the largest plan." },
95	];
96	
97	export default async function PricingPage() {
98	  // Every product line's prices — read live from the catalogue. Nothing below is
99	  // hard-coded; if a plan is edited or deactivated in the DB, this page follows.
100	  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
101	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
102	    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
103	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
104	    db.gamePlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
105	  ]);
106	
107	  // Group game plans by family, in canonical order, keeping only families that
108	  // actually have a real per-game plan (honesty: no per-game price is claimed
109	  // over a title that lacks one — those deploy on a plain VPS instead).
110	  const byGame = new Map<string, typeof gamePlans>();
111	  for (const g of gamePlans) {
112	    if (!byGame.has(g.gameFamily)) byGame.set(g.gameFamily, []);
113	    byGame.get(g.gameFamily)!.push(g);
114	  }
115	  const games = GAME_FAMILIES.filter((f) => (byGame.get(f)?.length ?? 0) > 0);
116	  const GAME_META: Record<string, { name: string; tag: string }> = {
117	    minecraft: { name: "Minecraft", tag: "Java & Bedrock" },
118	    valheim: { name: "Valheim", tag: "Dedicated world" },
119	    rust: { name: "Rust", tag: "High player counts" },
120	    palworld: { name: "Palworld", tag: "Co-op survival" },
121	    cs2: { name: "Counter-Strike 2", tag: "Competitive FPS" },
122	    terraria: { name: "Terraria", tag: "Sandbox worlds" },
123	  };
124	
125	  // Promo copy comes from the single source of truth. It is shown ONLY where the
126	  // owner scoped it — shared web hosting — via firstMonthFreeAppliesTo("HOSTING").
127	  const promo = currentPromo(new Date());
128	  const hostingHasPromo = firstMonthFreeAppliesTo("HOSTING");
129	
130	  // The REAL annual discount, read from the admin setting (lib/annual-discount.ts) —
131	  // never a hardcoded marketing number. The annual term genuinely exists in the
132	  // deploy wizard and is charged/renewed at this rate (lib/order.ts, renewalCharge),
133	  // so surfacing it here is honest. Only shown when it is actually a discount.
134	  const annualPct = await annualDiscountPct();
135	
136	  const vpsFrom = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;
137	
138	  // Cheapest plan per product line, for the "index" overview — every figure below
139	  // is the same DB record the section deep-dives read, so the summary and the
140	  // detail can never disagree.
141	  const cheapest = <T extends { priceCents: number }>(arr: T[]): T | null =>
142	    arr.length ? arr.reduce((a, b) => (b.priceCents < a.priceCents ? b : a)) : null;
143	  const planFrom = (p: { priceCents: number; termMonths?: number } | null): string =>
144	    p ? `${money(p.priceCents)}${p.termMonths && p.termMonths > 1 ? ` / ${p.termMonths} mo` : "/mo"}` : "—";
145	  const vpsMin = cheapest(vpsPlans);
146	  const gameMin = cheapest(gamePlans);
147	  const hostingMin = cheapest(hostingPlans);
148	  const emailMin = cheapest(emailPlans);
149	  const domainMin = POPULAR_TLDS.length ? Math.min(...POPULAR_TLDS.map((t) => t.fromCents)) : null;
150	
151	  // The product index (chooser + at-a-glance, merged). `from` is always DB-derived
152	  // (domains are the labelled "indicative" exception, matching the domains section).
153	  const INDEX: { icon: ReactNode; name: string; who: string; from: string; billing: string; href: string; accent: string }[] = [
154	    { icon: <IconTerminal />, name: "Cloud VPS", who: "Full root, any stack, resize on demand", from: planFrom(vpsMin), billing: "Monthly · resize anytime", href: "#vps", accent: "text-brand-300" },
155	    { icon: <IconGame />, name: "Game Servers", who: "Low-latency worlds, one-click deploy", from: gameMin ? `from ${planFrom(gameMin)}` : "—", billing: "Per game · monthly", href: "#game-servers", accent: "text-emerald-300" },
156	    { icon: <IconApps />, name: "Shared Hosting", who: "WordPress & SSL, no server to manage", from: planFrom(hostingMin), billing: hostingHasPromo ? "First month free · then monthly" : "Monthly · no lock-in", href: "#hosting", accent: "text-accent-cyan" },
157	    { icon: <IconMail />, name: "Business Email", who: "Mailboxes at your own domain", from: planFrom(emailMin), billing: "Monthly", href: "#email", accent: "text-sky-300" },
158	    { icon: <IconGlobe />, name: "Domains", who: "Register, manage DNS, point at your VPS", from: domainMin != null ? `from ${money(domainMin)}/yr*` : "—", billing: "Yearly registration", href: "#domains", accent: "text-brand-300" },
159	  ];
160	
161	  // The commitment ladder, worked on the entry VPS. Every figure runs the live
162	  // catalogue price through termPriceCents (the SAME formula checkout charges &
163	  // renewals bill) with the live admin annual rate — zero hard-coded prices.
164	  const longestMonths = VPS_TERMS[VPS_TERMS.length - 1].months;
165	  let ladderRungs: TermRung[] = [];
166	  let maxDiscountPct = 0;
167	  let bestSavingsLabel = "";
168	  if (vpsMin) {
169	    ladderRungs = VPS_TERMS.map((t) => {
170	      const total = termPriceCents(vpsMin.priceCents, t.months, annualPct);
171	      const perMo = Math.round(total / t.months);
172	      const savings = vpsMin.priceCents * t.months - total;
173	      const disc = t.months === ANNUAL_TERM_MONTHS ? annualPct : t.discountPct;
174	      const isLongest = t.months === longestMonths;
175	      return {
176	        label: t.label,
177	        short: t.short,
178	        perMoLabel: money(perMo),
179	        monthlyLabel: money(vpsMin.priceCents),
180	        totalLabel: money(total),
181	        cadenceLabel: t.months === 1 ? "monthly" : `every ${t.short}`,
182	        savingsLabel:
183	          savings > 0
184	            ? t.months === ANNUAL_TERM_MONTHS
185	              ? `Save ${money(savings)}/yr`
186	              : `Save ${money(savings)} over ${t.short}`
187	            : "Flexible — cancel anytime",
188	        discountPct: disc,
189	        hasSavings: savings > 0,
190	        recommended: t.months === ANNUAL_TERM_MONTHS,
191	        bestValue: isLongest && disc > 0,
192	      };
193	    });
194	    const longest = VPS_TERMS[VPS_TERMS.length - 1];
195	    maxDiscountPct = longest.discountPct;
196	    const longestSavings = vpsMin.priceCents * longest.months - termPriceCents(vpsMin.priceCents, longest.months, annualPct);
197	    bestSavingsLabel = longestSavings > 0 ? `That's ${money(longestSavings)} back in your pocket over ${longest.short}.` : "";
198	  }
199	
200	  return (
201	    <>
202	      {vpsPlans.length > 0 && <ProductJsonLd plans={vpsPlans} />}
203	      <FaqJsonLd items={FAQ} />
204	
205	      <div className="relative overflow-hidden">
206	        {/* Ambient dot-field — the v5 signature the owner likes — behind the whole page. */}
207	        <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
208	          <AmbientField />
209	          <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_45%_at_15%_-5%,rgba(111,71,245,0.16),transparent_60%),radial-gradient(ellipse_55%_40%_at_92%_0%,rgba(59,130,246,0.12),transparent_60%)]" />
210	        </div>
211	
212	        <div className="relative z-10">
213	          {/* ═══════════ HERO — asymmetric, speed-led ═══════════ */}
214	          <section className="rail grid items-center gap-12 py-16 lg:grid-cols-[1.08fr_0.92fr] lg:py-24">
215	            <Reveal>
216	              <span className="eyebrow-pill mb-6">
217	                <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan animate-pulse-dot" /> Pricing · every product, one wallet
218	              </span>
219	              <h1 className="text-[3.1rem] font-black leading-[0.92] tracking-tight text-white sm:text-[4.4rem]">
220	                Your server is<br />
221	                <span className="grad-text">47 seconds away.</span>
222	              </h1>
223	              <p className="mt-6 max-w-lg text-lg leading-relaxed text-slate-400">
224	                Cloud VPS, game servers, shared hosting, business email and domains — every price on this
225	                page is read live from checkout, billed from one wallet, with no lock-in.
226	              </p>
227	              <div className="mt-7 flex flex-wrap items-center gap-3">
228	                <Link href="/register" className="btn-primary px-6 py-3 text-base">Create your account →</Link>
229	                <Link href="#index" className="btn-secondary px-6 py-3 text-base">Find my product</Link>
230	                {vpsFrom != null && (
231	                  <span className="inline-flex items-baseline gap-1.5 rounded-xl border border-white/10 bg-white/[0.03] px-4 py-2.5 text-sm">
232	                    <span className="text-slate-400">VPS from</span>
233	                    <span className="font-bold text-white">{money(vpsFrom)}</span>
234	                    <span className="text-slate-500">/mo</span>
235	                  </span>
236	                )}
237	              </div>
238	              <p className="mt-5 flex flex-wrap gap-x-5 gap-y-2 text-xs text-slate-400">
239	                {["The price you sign up at is the price you renew at", "No lock-in — cancel anytime", "Free migration in"].map((t) => (
240	                  <span key={t} className="flex items-center gap-1.5"><span className="text-accent-cyan">✓</span>{t}</span>
241	                ))}
242	              </p>
243	              <div className="mt-7"><ReviewBadges /></div>
244	            </Reveal>
245	            <Reveal delay={140}>
246	              <div className="lg:pl-4"><DeployCard /></div>
247	            </Reveal>
248	          </section>
249	
250	          {/* ═══════════ MARQUEE — rhythm break ═══════════ */}
251	          <section className="tone-panel py-10">
252	            <div className="rail">
253	              <p className="text-center text-sm font-semibold uppercase tracking-[0.16em] text-slate-500">Deploy with any OS, panel or stack</p>
254	            </div>
255	            <div className="mt-7"><LogoMarquee /></div>
256	          </section>
257	
258	          {/* ═══════════ COMMITMENT LADDER — the persuasion centerpiece ═══════════ */}
259	          {vpsMin && (
260	            <section className="relative py-24 sm:py-28">
261	              <div className="pointer-events-none absolute inset-0 -z-10 hero-aura opacity-70" aria-hidden />
262	              <div className="rail">
263	                <TermLadder
264	                  planName={vpsMin.name}
265	                  planMonthlyLabel={money(vpsMin.priceCents)}
266	                  maxDiscountPct={maxDiscountPct}
267	                  bestSavingsLabel={bestSavingsLabel}
268	                  rungs={ladderRungs}
269	                />
270	              </div>
271	            </section>
272	          )}
273	
274	          {/* ═══════════ PRODUCT INDEX — chooser + at-a-glance, merged & asymmetric ═══════════ */}
275	          <section id="index" className="tone-panel py-20 sm:py-24 scroll-mt-24">
276	            <div className="rail grid gap-10 lg:grid-cols-[0.72fr_1.28fr] lg:items-start">
277	              <Reveal>
278	                <span className="eyebrow"><IconApps size={14} /> Where to start</span>
279	                <h2 className="mt-4 text-4xl font-bold leading-[1.05] tracking-tight text-white sm:text-5xl text-balance">
280	                  Five products.<br /><span className="grad-text">One account.</span>
281	                </h2>
282	                <p className="mt-5 max-w-sm text-[15px] leading-relaxed text-slate-400">
283	                  Tell us what you're building and jump straight to the real numbers — starting prices below
284	                  are read live from the same catalogue the checkout charges.
285	                </p>
286	              </Reveal>
287	              <Reveal delay={100}>
288	                <div className="grid gap-3">
289	                  {INDEX.map((o) => (
290	                    <a
291	                      key={o.name}
292	                      href={o.href}
293	                      className="card card-hover group grid grid-cols-[auto_1fr_auto] items-center gap-4 py-4"
294	                    >
295	                      <span className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 ${o.accent}`}>
296	                        {o.icon}
297	                      </span>
298	                      <span className="min-w-0">
299	                        <span className="flex items-center gap-2 font-semibold text-white transition-colors group-hover:text-brand-200">
300	                          {o.name} <IconArrow size={13} className="opacity-0 transition-opacity group-hover:opacity-100" />
301	                        </span>
302	                        <span className="mt-0.5 block truncate text-sm text-slate-400">{o.who}</span>
303	                      </span>
304	                      <span className="text-right">
305	                        <span className="block font-bold text-white">{o.from}</span>
306	                        <span className="mt-0.5 block text-[11px] text-slate-500">{o.billing}</span>
307	                      </span>
308	                    </a>
309	                  ))}
310	                </div>
311	                <p className="mt-4 text-sm text-slate-500">
312	                  *Domain prices are indicative per year — search a name for the exact live figure.
313	                </p>
314	              </Reveal>
315	            </div>
316	          </section>
317	
318	          {/* Sticky product switcher */}
319	          <PricingNav items={NAV} />
320	
321	          {/* ═══════════ VPS ═══════════ */}
322	          <Section size="lg" id="vps" className="scroll-mt-[150px]">
323	            <div className="flex flex-wrap items-end justify-between gap-6">
324	              <div className="max-w-xl">
325	                <span className="eyebrow"><IconTerminal size={14} /> Cloud VPS</span>
326	                <h2 className="mt-4 text-4xl font-bold tracking-tight text-white sm:text-5xl text-balance">Full-control virtual servers</h2>
327	                <p className="mt-4 text-lg leading-relaxed text-slate-400">
328	                  Root access, a dedicated IPv4, NVMe storage and DDoS protection on every plan — you only
329	                  choose how much horsepower you need. Billed monthly, resize anytime.
330	                </p>
331	              </div>
332	              {vpsFrom != null && (
333	                <div className="rounded-2xl border border-brand-500/20 bg-brand-500/[0.06] px-6 py-4">
334	                  <p className="text-[11px] font-semibold uppercase tracking-wider text-brand-200">Starts at</p>
335	                  <p className="mt-1 text-3xl font-black text-white">{money(vpsFrom)}<span className="text-base font-normal text-slate-400">/mo</span></p>
336	                </div>
337	              )}
338	            </div>
339	
340	            {vpsPlans.length === 0 ? (
341	              <p className="mt-10 text-slate-400">Plans are being provisioned — check back shortly.</p>
342	            ) : (
343	              <Reveal className="mt-10">
344	                <div className="card overflow-x-auto p-0">
345	                  <table className="table-shell min-w-[680px]">
346	                    <thead>
347	                      <tr>
348	                        <th>Plan</th>
349	                        {vpsPlans.map((p, i) => {
350	                          const popular = vpsPlans.length >= 3 && i === Math.floor((vpsPlans.length - 1) / 2);
351	                          const best = vpsPlans.length >= 3 && i === vpsPlans.length - 1;
352	                          return (
353	                            <th key={p.id} className="text-center">
354	                              <div className="flex flex-col items-center gap-1">
355	                                {popular ? (
356	                                  <span className="rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider text-white">Most popular</span>
357	                                ) : best ? (
358	                                  <span className="rounded-full border border-accent-cyan/40 bg-accent-cyan/10 px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider text-accent-cyan">Best value</span>
359	                                ) : (
360	                                  <span className="h-[16px]" />
361	                                )}
362	                                <span>{p.name}</span>
363	                              </div>
364	                              <div className="mt-1 text-sm font-bold text-white">{money(p.priceCents)}/mo</div>
365	                            </th>
366	                          );
367	                        })}
368	                      </tr>
369	                    </thead>
370	                    <tbody>
371	                      <tr>
372	                        <td className="font-medium text-slate-300">vCPU</td>
373	                        {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.cpuCores}</td>)}
374	                      </tr>
375	                      <tr>
376	                        <td className="font-medium text-slate-300">RAM</td>
377	                        {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{gb(p.ramMB)}</td>)}
378	                      </tr>
379	                      <tr>
380	                        <td className="font-medium text-slate-300">Storage</td>
381	                        {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.diskGB} GB</td>)}
382	                      </tr>
383	                      <tr>
384	                        <td className="font-medium text-slate-300">Bandwidth</td>
385	                        {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.bandwidthTB} TB</td>)}
386	                      </tr>
387	                      {VPS_FEATURES.map((feat) => (
388	                        <tr key={feat}>
389	                          <td className="font-medium text-slate-300">{feat}</td>
390	                          {vpsPlans.map((p) => (
391	                            <td key={p.id} className="text-center">
392	                              <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400"><IconCheck size={13} /></span>
393	                            </td>
394	                          ))}
