input.content:
"use client";

import Link from "next/link";
import { useState } from "react";
import {
  VPS_TERMS,
  PRODUCT_TERMS,
  termPriceCents,
  termDiscountPct,
  vpsEffectiveMonthly,
} from "@/lib/billing-terms";
import {
  IconServer,
  IconGame,
  IconApps,
  IconMail,
  IconGlobe,
  IconCheck,
  IconShield,
  IconBackup,
  IconNvme,
  IconGift,
  IconArrow,
  IconGauge,
} from "@/components/marketing/icons";

/* ────────────────────────────────────────────────────────────────────────────
   Serializable data contract. The server page (app/(marketing)/pricing/page.tsx)
   reads every plan LIVE from the catalogue (db.plan / db.gamePlan / db.hostingPlan
   / db.emailPlan) and hands each plan's BASE MONTHLY price down as `monthlyCents`.
   This component never hard-codes a price: it runs that DB number through the SAME
   pure money helpers checkout uses — termPriceCents / vpsEffectiveMonthly — so the
   "$/mo" it shows for a term is exactly what checkout charges for that term.
   ──────────────────────────────────────────────────────────────────────────── */

export type ExplorerSpec = { label: string; value: string };
export type ExplorerPlan = {
  id: string;
  name: string;
  monthlyCents: number;
  badge?: "popular" | "best";
  specs: ExplorerSpec[];
  href: string;
};
export type ExplorerGameFamily = { id: string; name: string; plans: ExplorerPlan[] };
export type ExplorerTld = { tld: string; fromCents: number };

export type ProductId = "vps" | "game" | "hosting" | "email" | "domains";

export type PricingExplorerProps = {
  annualPct: number;
  vps: ExplorerPlan[];
  hosting: ExplorerPlan[];
  email: ExplorerPlan[];
  games: ExplorerGameFamily[];
  tlds: ExplorerTld[];
  /** Non-null ONLY when firstMonthFreeAppliesTo("HOSTING") — gates the hosting badge. */
  hostingPromoLabel: string | null;
  included: Record<ProductId, string[]>;
  domainsHref: string;
};

/* Presentation-only maps (no prices live here). */
const PRODUCTS: { id: ProductId; label: string; Icon: typeof IconServer }[] = [
  { id: "vps", label: "Cloud VPS", Icon: IconServer },
  { id: "game", label: "Game Servers", Icon: IconGame },
  { id: "hosting", label: "Shared Hosting", Icon: IconApps },
  { id: "email", label: "Business Email", Icon: IconMail },
  { id: "domains", label: "Domains", Icon: IconGlobe },
];
const GAME_EMOJI: Record<string, string> = {
  minecraft: "⛏️", valheim: "⚔️", rust: "🔥", palworld: "🌐", cs2: "🎯", terraria: "🌿",
};

function money(cents: number): string {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

/* ── Live price for a plan at the selected term. Displayed === charged. ── */
function priceFor(monthlyCents: number, months: number, annualPct: number) {
  const perMo = vpsEffectiveMonthly(monthlyCents, months, annualPct);
  const total = termPriceCents(monthlyCents, months, annualPct);
  const savingOverTerm = monthlyCents * months - total;
  const savingPerYear = Math.round((monthlyCents - perMo) * 12);
  return { perMo, total, savingOverTerm, savingPerYear };
}

export function PricingExplorer(props: PricingExplorerProps) {
  const { annualPct } = props;
  const [product, setProduct] = useState<ProductId>("vps");
  // Annual pre-selected by default — nudges the longer, cheaper commitment.
  const [months, setMonths] = useState<number>(12);
  const [family, setFamily] = useState<string>(props.games[0]?.id ?? "");

  const isVps = product === "vps";
  const termList = isVps ? VPS_TERMS : PRODUCT_TERMS;
  // Guard against an out-of-range term after a product switch (e.g. Triennial on VPS
  // → Business Email, which only sells Monthly/Annual). Falls back to Annual.
  const effMonths = termList.some((t) => t.months === months)
    ? months
    : termList.some((t) => t.months === 12)
      ? 12
      : 1;
  const activeIdx = Math.max(0, termList.findIndex((t) => t.months === effMonths));

  const activeGame = props.games.find((g) => g.id === family) ?? props.games[0];
  const panelPlans: ExplorerPlan[] =
    product === "vps" ? props.vps
      : product === "hosting" ? props.hosting
      : product === "email" ? props.email
      : product === "game" ? (activeGame?.plans ?? [])
      : [];

  // Live "from / you save" readout — the cheapest plan on the current panel.
  const cheapest = panelPlans.length
    ? panelPlans.reduce((a, b) => (b.monthlyCents < a.monthlyCents ? b : a))
    : null;
  const readout = cheapest ? priceFor(cheapest.monthlyCents, effMonths, annualPct) : null;

  return (
    <div className="rail">
      {/* ── Compact header / wordmark ── */}
      <div className="flex flex-col items-center pt-14 pb-8 text-center sm:pt-20">
        <span className="eyebrow-pill mb-5">
          <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan animate-pulse-dot" /> Nxeon · Pricing
        </span>
        <h1 className="text-4xl font-black tracking-tight text-white sm:text-5xl">
          Lock in your price <span className="grad-text">today.</span>
        </h1>
        <p className="mt-4 max-w-md text-[15px] leading-relaxed text-slate-400">
          The price you sign up at is the price you renew at — it never increases at renewal.
          No lock-in, cancel anytime.
        </p>
        <div className="mt-4 flex items-center gap-2 text-xs text-slate-500">
          <span className="tracking-[0.2em] text-amber-300" aria-hidden>★★★★★</span>
          <span>Loved by builders shipping real things — first website to full fleet</span>
        </div>
      </div>

      {/* ── Product tab row ── */}
      <div
        role="tablist"
        aria-label="Product"
        className="-mx-5 flex items-center gap-1 overflow-x-auto px-5 pb-1 sm:mx-0 sm:justify-center sm:gap-2 sm:overflow-visible sm:px-0"
      >
        {PRODUCTS.map(({ id, label, Icon }) => {
          const active = product === id;
          return (
            <button
              key={id}
              role="tab"
              aria-selected={active}
              onClick={() => setProduct(id)}
              className={`group relative flex shrink-0 items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-all duration-200 ${
                active ? "text-white" : "text-slate-400 hover:text-slate-200"
              }`}
            >
              <Icon size={16} className={active ? "text-accent-cyan" : "opacity-70"} />
              {label}
              <span
                aria-hidden
                className={`pointer-events-none absolute inset-x-3 -bottom-px h-[2px] rounded-full bg-gradient-to-r from-accent-blue via-brand-400 to-accent-cyan transition-all duration-300 ${
                  active ? "opacity-100" : "opacity-0"
                }`}
                style={active ? { boxShadow: "0 0 14px 1px rgba(34,211,238,0.55)" } : undefined}
              />
            </button>
          );
        })}
      </div>

      {/* ── Billing-cycle toggle + live savings readout ── */}
      <div className="mt-5 flex flex-col gap-4 border-t border-white/[0.06] pt-5 md:flex-row md:items-center md:justify-between">
        <div className="flex flex-wrap items-center gap-3">
          <span className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-500">Billing cycle</span>
          <div
            role="tablist"
            aria-label="Billing cycle"
            className="relative grid rounded-full border border-white/10 bg-white/[0.03] p-1"
            style={{ gridTemplateColumns: `repeat(${termList.length}, minmax(0,1fr))` }}
          >
            {/* Sliding gradient thumb — equal columns, so it tracks cleanly. */}
            <span
              aria-hidden
              className="absolute inset-y-1 rounded-full bg-gradient-to-r from-brand-500 to-accent-cyan shadow-[0_4px_18px_-4px_rgba(111,71,245,0.7)] transition-transform duration-300 ease-out motion-reduce:transition-none"
              style={{
                width: `calc((100% - 0.5rem) / ${termList.length})`,
                left: "0.25rem",
                transform: `translateX(${activeIdx * 100}%)`,
              }}
            />
            {termList.map((t) => {
              const active = t.months === effMonths;
              const pct = termDiscountPct(t.months, annualPct);
              return (
                <button
                  key={t.months}
                  role="tab"
                  aria-selected={active}
                  onClick={() => setMonths(t.months)}
                  className={`relative z-10 flex items-center justify-center gap-1.5 whitespace-nowrap rounded-full px-3.5 py-1.5 text-[13px] font-semibold transition-colors ${
                    active ? "text-white" : "text-slate-400 hover:text-slate-200"
                  }`}
                >
                  {t.label}
                  {pct > 0 && (
                    <span
                      className={`rounded px-1 py-px text-[10px] font-bold ${
                        active ? "bg-black/25 text-white" : "bg-accent-cyan/15 text-accent-cyan"
                      }`}
                    >
                      −{pct}%
                    </span>
                  )}
                </button>
              );
            })}
          </div>
          <span className="text-xs text-slate-500">Multi-year applies to VPS only.</span>
        </div>

        {/* Live readout — re-keyed on every product/term change so it pops. */}
        {readout && (
          <div
            key={`${product}-${effMonths}`}
            className="motion-safe:animate-price-pop flex items-baseline gap-2 rounded-xl border border-accent-cyan/20 bg-accent-cyan/[0.06] px-4 py-2 text-sm"
          >
            <IconGauge size={15} className="translate-y-0.5 text-accent-cyan" />
            <span className="text-slate-400">Effective from</span>
            <span className="text-lg font-black text-white">{money(readout.perMo)}</span>
            <span className="text-slate-500">/mo</span>
            {effMonths > 1 && readout.savingPerYear > 0 && (
              <span className="font-semibold text-accent-cyan">· save {money(readout.savingPerYear)}/yr</span>
            )}
          </div>
        )}
      </div>

      {/* ── Product panel — re-keyed so it animates in on every tab switch ── */}
      <div key={product} className="motion-safe:animate-panel-in mt-8">
        {product === "domains" ? (
          <DomainsPanel tlds={props.tlds} href={props.domainsHref} />
        ) : (
          <>
            {/* Hosting-only first-month-free badge + game family sub-tabs */}
            {product === "hosting" && props.hostingPromoLabel && (
              <div className="mb-6 inline-flex items-center gap-2 rounded-full border border-accent-cyan/30 bg-accent-cyan/10 px-4 py-1.5 text-sm font-semibold text-accent-cyan">
                <IconGift size={15} /> {props.hostingPromoLabel} · on all plans
              </div>
            )}
            {product === "game" && props.games.length > 0 && (
              <div className="mb-6 flex flex-wrap gap-2">
                {props.games.map((g) => {
                  const active = g.id === (activeGame?.id ?? "");
                  return (
                    <button
                      key={g.id}
                      onClick={() => setFamily(g.id)}
                      className={`flex items-center gap-2 rounded-xl border px-3.5 py-2 text-sm font-medium transition-all duration-200 ${
                        active
                          ? "border-accent-cyan/50 bg-accent-cyan/10 text-white shadow-[0_0_20px_-8px_rgba(34,211,238,0.7)]"
                          : "border-white/[0.08] bg-white/[0.02] text-slate-400 hover:border-white/20 hover:text-slate-200"
                      }`}
                    >
                      <span aria-hidden>{GAME_EMOJI[g.id] ?? "🎮"}</span>
                      {g.name}
                    </button>
                  );
                })}
              </div>
            )}

            {panelPlans.length === 0 ? (
              <p className="py-10 text-center text-slate-400">Plans are being provisioned — check back shortly.</p>
            ) : (
              <div
                className={`grid gap-4 ${
                  panelPlans.length >= 4
                    ? "sm:grid-cols-2 lg:grid-cols-4"
                    : panelPlans.length === 3
                      ? "sm:grid-cols-2 lg:grid-cols-3"
                      : panelPlans.length === 2
                        ? "sm:grid-cols-2"
                        : "sm:grid-cols-2 lg:grid-cols-3"
                }`}
              >
                {panelPlans.map((p) => (
                  <PlanCard key={p.id} plan={p} months={effMonths} annualPct={annualPct} />
                ))}
              </div>
            )}

            {/* Trust microcopy near the CTAs — remove friction. */}
            <p className="mt-4 text-center text-xs text-slate-500">
              The price you sign up at is the price you renew at · no lock-in, cancel anytime
              {product === "hosting" && props.hostingPromoLabel
                ? " · first month free, then the regular monthly price shown"
                : ""}
            </p>

            {/* Included-with-all-plans strip (product-specific). */}
            <div className="mt-7 rounded-2xl border border-white/[0.06] bg-navy-900/40 px-5 py-4 backdrop-blur-md">
              <p className="section-label mb-3">Included with all plans</p>
              <div className="flex flex-wrap gap-x-6 gap-y-2">
                {props.included[product].map((f) => (
                  <span key={f} className="flex items-center gap-1.5 text-sm text-slate-300">
                    <span className="inline-flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                      <IconCheck size={11} />
                    </span>
                    {f}
                  </span>
                ))}
              </div>
            </div>
          </>
        )}
      </div>

      {/* ── Trust footer ── */}
      <div className="mt-8 flex flex-wrap items-center justify-center gap-x-6 gap-y-3 border-t border-white/[0.06] pt-6 pb-14 text-xs text-slate-400">
        {[
          { icon: <IconShield size={14} />, t: "DDoS protected" },
          { icon: <IconGauge size={14} />, t: "Prepaid wallet · cancel anytime" },
          { icon: <IconBackup size={14} />, t: "Auto backups" },
          { icon: <IconNvme size={14} />, t: "NVMe everywhere" },
          { icon: <IconArrow size={14} />, t: "Free migration assistance" },
        ].map((x) => (
          <span key={x.t} className="flex items-center gap-1.5">
            <span className="text-brand-300">{x.icon}</span>
            {x.t}
          </span>
        ))}
      </div>
    </div>
  );
}

/* ── One plan card ── */
function PlanCard({ plan, months, annualPct }: { plan: ExplorerPlan; months: number; annualPct: number }) {
  const { perMo, total, savingOverTerm } = priceFor(plan.monthlyCents, months, annualPct);
  const popular = plan.badge === "popular";
  const best = plan.badge === "best";
  const short = (VPS_TERMS.find((t) => t.months === months) ?? PRODUCT_TERMS[0]).short;

  return (
    <div
      className={`card lift group relative flex h-full flex-col ${
        popular
          ? "border-brand-500/50 bg-navy-850/80 ring-1 ring-brand-500/30 glow-brand"
          : best
            ? "border-accent-cyan/40 ring-1 ring-accent-cyan/25"
            : ""
      }`}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="font-semibold text-white">{plan.name}</span>
        {popular && (
          <span className="rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-white">
            Most popular
          </span>
        )}
        {best && (
          <span className="rounded-full border border-accent-cyan/40 bg-accent-cyan/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-accent-cyan">
            Best value
          </span>
        )}
      </div>

      {/* Re-keyed on term change → the number visibly pops. */}
      <div key={months} className="motion-safe:animate-price-pop mt-3">
        <span className="text-4xl font-black tracking-tight text-white">{money(perMo)}</span>
        <span className="text-sm font-normal text-slate-400">/mo</span>
      </div>
      <p className="mt-1 h-4 text-[11px] text-slate-500">
        {months > 1
          ? `${money(total)} billed every ${short}${savingOverTerm > 0 ? ` · save ${money(savingOverTerm)}` : ""}`
          : "Billed monthly"}
      </p>

      <div className="mt-4 space-y-2 border-t border-white/[0.05] pt-4">
        {plan.specs.map((s) => (
          <div key={s.label} className="flex items-center justify-between text-sm">
            <span className="text-slate-400">{s.label}</span>
            <span className="font-mono font-semibold text-slate-200">{s.value}</span>
          </div>
        ))}
      </div>

      <Link
        href={plan.href}
        className={`mt-5 w-full text-center ${popular ? "btn-primary" : "btn-secondary"}`}
      >
        Deploy Now
      </Link>
    </div>
  );
}

/* ── Domains TLD grid ── */
function DomainsPanel({ tlds, href }: { tlds: ExplorerTld[]; href: string }) {
  return (
    <>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
        {tlds.map((t) => (
          <div
            key={t.tld}
            className="group flex items-center justify-between rounded-2xl border border-white/[0.06] bg-navy-900/60 px-4 py-3 backdrop-blur-md transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30 hover:bg-navy-850/70"
          >
            <span className="font-mono text-base font-bold text-white">{t.tld}</span>
            <span className="text-right text-xs">
              <span className="text-slate-500">from </span>
              <span className="font-semibold text-brand-300">{money(t.fromCents)}/yr</span>
            </span>
          </div>
        ))}
      </div>
      <p className="mt-4 text-center text-xs text-slate-500">
        Indicative starting prices per year — premium names are priced individually.{" "}
        <Link href={href} className="text-brand-300 hover:underline">Search a name for the exact live figure →</Link>
      </p>
    </>
  );
}

import type { Metadata } from "next";
import { db } from "@/lib/db";
import { GAME_FAMILIES } from "@/lib/games";
import { currentPromo } from "@/lib/promotions";
import { firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
import { annualDiscountPct } from "@/lib/annual-discount";
import { AmbientField } from "@/components/marketing/AmbientField";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import { ProductJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
