1	/**
2	 * Per-server extra disk — pure, dependency-free maths + copy.
3	 *
4	 * Deliberately has NO server-only imports (no db, no settings) so the exact same
5	 * module can be imported by client components (DeployWizard, AddStorage) and by
6	 * the server actions / worker. Whatever the customer SEES is byte-for-byte what
7	 * gets CHARGED — mirroring lib/wallet-split.ts.
8	 *
9	 * This is the server's OWN root disk growing, which is a different product from
10	 * block-storage volumes (lib/actions-volumes.ts): a volume is portable and can be
11	 * detached and deleted; this space is fused into the VM's root filesystem.
12	 *
13	 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
14	 * A live filesystem cannot be shrunk without risking data loss, and no serious
15	 * provider offers it. There is NO shrink path anywhere in the platform, and
16	 * `Server.extraDiskGB` is never decremented. Every surface that sells extra
17	 * storage must show EXTRA_DISK_ONE_WAY_NOTE before taking the money.
18	 */
19	
20	/** Storage is sold in 10 GB increments — matches the slider/step in both UIs. */
21	export const EXTRA_DISK_STEP_GB = 10;
22	/** Smallest purchasable amount. */
23	export const EXTRA_DISK_MIN_GB = 10;
24	/** Largest amount purchasable in a SINGLE transaction. */
25	export const EXTRA_DISK_MAX_ADD_GB = 500;
26	/** Hard ceiling on a server's effective disk (plan.diskGB + extraDiskGB). */
27	export const EXTRA_DISK_MAX_TOTAL_GB = 2000;
28	/**
29	 * Fallback price per GB per month when the `extra_disk_gb_price_cents` admin
30	 * setting has never been written. 10 = $0.10/GB/mo, matching block storage.
31	 * Use `extraDiskMonthlyCents()` (lib/disk-expand.ts) in billing paths, never this.
32	 */
33	export const EXTRA_DISK_DEFAULT_PER_GB_CENTS = 10;
34	
35	/** The one-way warning, shown verbatim on every surface that sells extra disk. */
36	export const EXTRA_DISK_ONE_WAY_NOTE =
37	  "Storage can only be added, never removed. Extra disk space is permanent for this server's lifetime and keeps billing every cycle.";
38	
39	/** A server's EFFECTIVE root disk in GB — plan allowance plus purchased extra. */
40	export function effectiveDiskGB(planDiskGB: number, extraDiskGB: number | null | undefined): number {
41	  return Math.max(0, Math.round(planDiskGB)) + Math.max(0, Math.round(extraDiskGB ?? 0));
42	}
43	
44	/**
45	 * Monthly cost (integer cents) of `gb` extra GB at `perGbCents`. Exact integer
46	 * multiplication — no floating-point money.
47	 */
48	export function extraDiskCentsAt(gb: number, perGbCents: number): number {
49	  const g = Math.max(0, Math.round(gb));
50	  const p = Math.max(0, Math.round(perGbCents));
51	  return g * p;
52	}
53	
54	/**
55	 * The one-off charge for `monthlyCents` of extra disk over the months still left
56	 * on the current paid term. THE single definition, shared by the server
57	 * (lib/disk-expand.ts diskExpandQuote) and the control that DISPLAYS the figure
58	 * before the customer agrees to it (components/customer/AddStorage.tsx).
59	 *
60	 * It lives in this pure module for exactly the reason `walletSplit` does: the
61	 * client has to be able to import it, so what is shown is byte-for-byte what is
62	 * charged. Until 2026-07-27 the server computed
63	 * `Math.max(0, Math.round(monthlyCents * remainingMonths))` and AddStorage computed
64	 * the same expression over its OWN private copy of `MS_PER_AVG_MONTH` — the two
65	 * places agreeing by convention that this codebase has been bitten by repeatedly
66	 * (the wizard's promo line, the "+30 days" renew button, the resize picker before
67	 * it was moved onto lib/proration.ts). Pass `remainingMonths(expiresAt, now)` from
68	 * lib/proration.ts as the second argument; do not re-derive it.
69	 *
70	 * Clamped at both ends: an expired term (negative months) prorates to zero rather
71	 * than crediting, and a negative price can never come out as a negative charge.
72	 */
73	export function extraDiskProrateCents(monthlyCents: number, monthsRemaining: number): number {
74	  const monthly = Math.max(0, monthlyCents);
75	  const months = Math.max(0, monthsRemaining);
76	  if (!Number.isFinite(monthly) || !Number.isFinite(months)) return 0;
77	  return Math.max(0, Math.round(monthly * months));
78	}
79	
80	/** Is `gb` a purchasable amount (a positive multiple of the step, within range)? */
81	export function isValidExtraDiskAddGB(gb: number): boolean {
82	  return (
83	    Number.isInteger(gb) &&
84	    gb >= EXTRA_DISK_MIN_GB &&
85	    gb <= EXTRA_DISK_MAX_ADD_GB &&
86	    gb % EXTRA_DISK_STEP_GB === 0
87	  );
88	}
89	
90	/**
91	 * Coerce arbitrary input to a purchasable amount: rounded DOWN to the step and
92	 * clamped to [0, EXTRA_DISK_MAX_ADD_GB]. Rounding DOWN (never up) means a
93	 * malformed value can only ever cost the customer less, never more. Returns 0
94	 * for "no extra disk", which every caller treats as a no-op.
95	 */
96	export function normalizeExtraDiskGB(gb: unknown): number {
97	  const n = Number(gb);
98	  if (!Number.isFinite(n) || n <= 0) return 0;
99	  const stepped = Math.floor(n / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB;
100	  if (stepped < EXTRA_DISK_MIN_GB) return 0;
101	  return Math.min(EXTRA_DISK_MAX_ADD_GB, stepped);
102	}
103	
104	/** Selectable amounts for the wizard/server-page controls: 10…500 GB by 10. */
105	export function extraDiskOptions(): number[] {
106	  const out: number[] = [];
107	  for (let g = EXTRA_DISK_MIN_GB; g <= EXTRA_DISK_MAX_ADD_GB; g += EXTRA_DISK_STEP_GB) out.push(g);
108	  return out;
109	}
110	
111	/**
112	 * The largest amount a server can still add without breaching the effective-disk
113	 * ceiling, rounded DOWN to the step. 0 means "already at the ceiling".
114	 */
115	export function maxAddableExtraDiskGB(planDiskGB: number, extraDiskGB: number): number {
116	  const headroom = EXTRA_DISK_MAX_TOTAL_GB - effectiveDiskGB(planDiskGB, extraDiskGB);
117	  if (headroom < EXTRA_DISK_MIN_GB) return 0;
118	  return Math.min(EXTRA_DISK_MAX_ADD_GB, Math.floor(headroom / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB);
119	}
120	
121	/** Human label for an extra-disk line item / notification. */
122	export function extraDiskLabel(gb: number): string {
123	  return `${Math.max(0, Math.round(gb))} GB extra disk storage`;
124	}
