/* ────────────────────────────────────────────────────────────────────────────
   Serializable data contract. The server page reads every plan LIVE from the
   catalogue (db.plan / db.gamePlan / db.hostingPlan / db.emailPlan) and hands each
   plan's BASE MONTHLY price down as `monthlyCents`. This component never hard-codes
   a price: it runs that DB number through the SAME pure money helpers checkout uses
   — termPriceCents / vpsEffectiveMonthly, plus extraDiskCentsAt for the storage
   add-on and the server-resolved backupPlusCents for the backup add-on — so what it
   shows for a term/add-on is exactly what checkout charges.
   ──────────────────────────────────────────────────────────────────────────── */

export type ExplorerSpec = { label: string; value: string };
export type ExplorerPlan = {
  id: string;
  name: string;
  monthlyCents: number;
  badge?: "popular" | "best";
  specs: ExplorerSpec[];
  href: string;
};
export type ExplorerGameFamily = { id: string; name: string; plans: ExplorerPlan[] };
export type ExplorerTld = { tld: string; fromCents: number };

export type ProductId = "vps" | "game" | "hosting" | "email" | "domains";

export type PricingExplorerProps = {
  annualPct: number;
  vps: ExplorerPlan[];
  hosting: ExplorerPlan[];
  email: ExplorerPlan[];
  games: ExplorerGameFamily[];
  tlds: ExplorerTld[];
  /** Non-null ONLY when firstMonthFreeAppliesTo("HOSTING") — gates the hosting badge. */
  hostingPromoLabel: string | null;
  included: Record<ProductId, string[]>;
  domainsHref: string;
  /** Live add-on prices, resolved server-side from the same settings checkout bills. */
  backupPlusCents: number;
  extraDiskPerGbCents: number;
  /** Server-rendered <ReviewBadges /> (Trustpilot · HostAdvice · Google). */
  reviewBadges?: ReactNode;
};

