  },
};

const PRODUCTS: { id: ProductId; label: string; Icon: typeof IconServer }[] = [
  { id: "vps", label: "Cloud VPS", Icon: IconServer },
  { id: "game", label: "Game Servers", Icon: IconGame },
  { id: "hosting", label: "Shared Hosting", Icon: IconApps },
  { id: "email", label: "Business Email", Icon: IconMail },
  { id: "domains", label: "Domains", Icon: IconGlobe },
];
const GAME_EMOJI: Record<string, string> = {
  minecraft: "⛏️", valheim: "⚔️", rust: "🔥", palworld: "🌐", cs2: "🎯", terraria: "🌿",
};

function money(cents: number): string {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

/* ── Live price for a plan at the selected term. Displayed === charged. ── */
function priceFor(monthlyCents: number, months: number, annualPct: number) {
  const perMo = vpsEffectiveMonthly(monthlyCents, months, annualPct);
  const total = termPriceCents(monthlyCents, months, annualPct);
  const savingOverTerm = monthlyCents * months - total;
  const savingPerYear = Math.round((monthlyCents - perMo) * 12);
  return { perMo, total, savingOverTerm, savingPerYear };
}

export function PricingExplorer(props: PricingExplorerProps) {
  const { annualPct } = props;
  const [product, setProduct] = useState<ProductId>("vps");
  // Annual pre-selected by default — nudges the longer, cheaper commitment.
  const [months, setMonths] = useState<number>(12);
  const [family, setFamily] = useState<string>(props.games[0]?.id ?? "");

  const accent = ACCENTS[product];
  const isVps = product === "vps";
  const isDomains = product === "domains";
  const termList = isVps ? VPS_TERMS : PRODUCT_TERMS;
  // Guard against an out-of-range term after a product switch (e.g. Triennial on VPS
  // → Business Email, which only sells Monthly/Annual). Falls back to Annual.
  const effMonths = termList.some((t) => t.months === months)
    ? months
    : termList.some((t) => t.months === 12)
      ? 12
      : 1;
  const activeIdx = Math.max(0, termList.findIndex((t) => t.months === effMonths));

  const activeGame = props.games.find((g) => g.id === family) ?? props.games[0];
  const panelPlans: ExplorerPlan[] =
    product === "vps" ? props.vps
      : product === "hosting" ? props.hosting
      : product === "email" ? props.email
      : product === "game" ? (activeGame?.plans ?? [])
      : [];

  // Live "from / you save" readout — the cheapest plan on the current panel.
  const cheapest = panelPlans.length
    ? panelPlans.reduce((a, b) => (b.monthlyCents < a.monthlyCents ? b : a))
    : null;
  const readout = cheapest ? priceFor(cheapest.monthlyCents, effMonths, annualPct) : null;

  return (
    <div className="rail">
      {/* ── Compact header / wordmark ── */}
      <div className="flex flex-col items-center pt-14 pb-8 text-center sm:pt-20">
        <span className="eyebrow-pill mb-5">
          <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan animate-pulse-dot" /> Nxeon · Pricing
        </span>
        <h1 className="text-4xl font-black tracking-tight text-white sm:text-5xl">
          Lock in your price <span className="grad-text">today.</span>
        </h1>
        <p className="mt-4 max-w-md text-[15px] leading-relaxed text-slate-400">
          The price you sign up at is the price you renew at — it never increases at renewal.
          No lock-in, cancel anytime.
        </p>
        {props.reviewBadges && <div className="mt-6 flex justify-center">{props.reviewBadges}</div>}
      </div>

      {/* ── Product tab row ── */}
      <div
        role="tablist"
        aria-label="Product"
        className="-mx-5 flex items-center gap-1 overflow-x-auto px-5 pb-1 sm:mx-0 sm:justify-center sm:gap-2 sm:overflow-visible sm:px-0"
      >
        {PRODUCTS.map(({ id, label, Icon }) => {
          const active = product === id;
          const a = ACCENTS[id];
          return (
            <button
              key={id}
              role="tab"
              aria-selected={active}
              onClick={() => setProduct(id)}
              className={`group relative flex shrink-0 items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-all duration-200 ${
                active ? "text-white" : "text-slate-400 hover:text-slate-200"
              }`}
            >
              <Icon size={16} className={active ? a.icon : "opacity-70"} />
              {label}
              <span
                aria-hidden
                className={`pointer-events-none absolute inset-x-3 -bottom-px h-[2px] rounded-full bg-gradient-to-r ${a.bar} transition-all duration-300 ${
                  active ? "opacity-100" : "opacity-0"
                }`}
                style={active ? { boxShadow: `0 0 14px 1px ${a.glow}` } : undefined}
              />
            </button>
          );
        })}
      </div>

      {/* ── Billing-cycle toggle + live savings readout (hidden for Domains) ── */}
      {!isDomains && (
        <div className="mt-5 flex flex-col gap-4 border-t border-white/[0.06] pt-5 md:flex-row md:items-center md:justify-between">
          <div className="flex flex-wrap items-center gap-3">
            <span className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-500">Billing cycle</span>
            <div
              role="tablist"
              aria-label="Billing cycle"
              className="relative grid rounded-full border border-white/10 bg-white/[0.03] p-1"
              style={{ gridTemplateColumns: `repeat(${termList.length}, minmax(0,1fr))` }}
            >
              {/* Sliding gradient thumb — equal columns, so it tracks cleanly. */}
              <span
                aria-hidden
                className={`absolute inset-y-1 rounded-full bg-gradient-to-r ${accent.thumb} transition-transform duration-300 ease-out motion-reduce:transition-none`}
                style={{
                  width: `calc((100% - 0.5rem) / ${termList.length})`,
                  left: "0.25rem",
                  transform: `translateX(${activeIdx * 100}%)`,
                  boxShadow: `0 4px 18px -4px ${accent.glow}`,
                }}
              />
              {termList.map((t) => {
                const active = t.months === effMonths;
                const pct = termDiscountPct(t.months, annualPct);
                return (
                  <button
                    key={t.months}
                    role="tab"
                    aria-selected={active}
                    onClick={() => setMonths(t.months)}
                    className={`relative z-10 flex items-center justify-center gap-1.5 whitespace-nowrap rounded-full px-3.5 py-1.5 text-[13px] font-semibold transition-colors ${
                      active ? "text-white" : "text-slate-400 hover:text-slate-200"
                    }`}
                  >
                    {t.label}
                    {pct > 0 && (
                      <span className={`rounded px-1 py-px text-[10px] font-bold ${active ? "bg-black/25 text-white" : accent.chip}`}>
                        −{pct}%
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
            <span className="text-xs text-slate-500">Multi-year applies to VPS only.</span>
          </div>

          {/* Live readout — re-keyed on every product/term change so it pops. */}
          {readout && (
            <div
              key={`${product}-${effMonths}`}
              className={`motion-safe:animate-price-pop flex items-baseline gap-2 rounded-xl border px-4 py-2 text-sm ${accent.readoutBox}`}
            >
              <IconGauge size={15} className={`translate-y-0.5 ${accent.readoutText}`} />
              <span className="text-slate-400">Effective from</span>
              <span className="text-lg font-black text-white">{money(readout.perMo)}</span>
              <span className="text-slate-500">/mo</span>
              {effMonths > 1 && readout.savingPerYear > 0 && (
                <span className={`font-semibold ${accent.readoutText}`}>· save {money(readout.savingPerYear)}/yr</span>
              )}
            </div>
          )}
        </div>
      )}

      {/* ── Product panel — re-keyed so it animates in on every tab switch ── */}
      <div key={product} className="motion-safe:animate-panel-in relative mt-8">
        {/* Per-service aura behind the panel head. */}
        <div
          aria-hidden
          className="pointer-events-none absolute -inset-x-6 -top-10 -z-10 h-72"
          style={{
            background: `radial-gradient(ellipse 45% 100% at 28% 0%, rgba(${accent.aura1},0.16), transparent 70%), radial-gradient(ellipse 38% 100% at 82% 0%, rgba(${accent.aura2},0.12), transparent 70%)`,
          }}
        />

        {isDomains ? (
          <DomainsPanel tlds={props.tlds} href={props.domainsHref} accent={accent} />
        ) : (
          <>
            {/* Hosting-only first-month-free badge + game family sub-tabs */}
            {product === "hosting" && props.hostingPromoLabel && (
              <div className="mb-6 inline-flex items-center gap-2 rounded-full border border-accent-cyan/30 bg-accent-cyan/10 px-4 py-1.5 text-sm font-semibold text-accent-cyan">
                <IconGift size={15} /> {props.hostingPromoLabel} · on all plans
              </div>
            )}
            {product === "game" && props.games.length > 0 && (
              <div className="mb-6 flex flex-wrap gap-2">
                {props.games.map((g) => {
                  const active = g.id === (activeGame?.id ?? "");
                  return (
                    <button
                      key={g.id}
                      onClick={() => setFamily(g.id)}
                      className={`flex items-center gap-2 rounded-xl border px-3.5 py-2 text-sm font-medium transition-all duration-200 ${
                        active
                          ? `${accent.gamePill} text-white`
                          : "border-white/[0.08] bg-white/[0.02] text-slate-400 hover:border-white/20 hover:text-slate-200"
                      }`}
                      style={active ? { boxShadow: `0 0 20px -8px ${accent.glow}` } : undefined}
                    >
                      <span aria-hidden>{GAME_EMOJI[g.id] ?? "🎮"}</span>
                      {g.name}
                    </button>
                  );
                })}
              </div>
            )}

            {panelPlans.length === 0 ? (
              <p className="py-10 text-center text-slate-400">Plans are being provisioned — check back shortly.</p>
            ) : (
              <div
                className={`grid gap-4 ${
                  panelPlans.length >= 4
                    ? "sm:grid-cols-2 lg:grid-cols-4"
                    : panelPlans.length === 3
                      ? "sm:grid-cols-2 lg:grid-cols-3"
                      : panelPlans.length === 2
                        ? "sm:grid-cols-2"
                        : "sm:grid-cols-2 lg:grid-cols-3"
                }`}
              >
                {panelPlans.map((p) => (
                  <PlanCard key={p.id} plan={p} months={effMonths} annualPct={annualPct} accent={accent} />
                ))}
              </div>
            )}

            {/* Trust microcopy near the CTAs — remove friction. */}
            <p className="mt-4 text-center text-xs text-slate-500">
              The price you sign up at is the price you renew at · no lock-in, cancel anytime
              {product === "hosting" && props.hostingPromoLabel
                ? " · first month free, then the regular monthly price shown"
                : ""}
            </p>

            {/* Value band: an animated product "screen" + (VPS) the add-on builder. */}
            <div className={`mt-8 grid gap-5 ${isVps ? "lg:grid-cols-[1fr_1fr]" : "mx-auto max-w-lg"}`}>
              <ProductScreen product={product} />
              {isVps && (
                <AddOnBuilder
                  plans={props.vps}
                  months={effMonths}
                  annualPct={annualPct}
                  backupPlusCents={props.backupPlusCents}
                  perGbCents={props.extraDiskPerGbCents}
                  accent={accent}
                />
              )}
            </div>
          </>
        )}

        {/* Included-with-all-plans strip (product-specific, centered). */}
        <div className="mt-7 rounded-2xl border border-white/[0.06] bg-navy-900/40 px-5 py-5 text-center backdrop-blur-md">
          <p className="section-label mb-3">Included with all plans</p>
          <div className="flex flex-wrap justify-center gap-x-6 gap-y-2">
            {props.included[product].map((f) => (
              <span key={f} className="flex items-center gap-1.5 text-sm text-slate-300">
                <span className="inline-flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                  <IconCheck size={11} />
                </span>
                {f}
              </span>
            ))}
          </div>
        </div>
      </div>

      {/* ── Trust footer ── */}
      <div className="mt-8 flex flex-wrap items-center justify-center gap-x-6 gap-y-3 border-t border-white/[0.06] pt-6 pb-14 text-xs text-slate-400">
        {[
          { icon: <IconShield size={14} />, t: "DDoS protected" },
          { icon: <IconGauge size={14} />, t: "Prepaid wallet · cancel anytime" },
          { icon: <IconBackup size={14} />, t: "Auto backups" },
          { icon: <IconNvme size={14} />, t: "NVMe everywhere" },
          { icon: <IconArrow size={14} />, t: "Free migration assistance" },
        ].map((x) => (
          <span key={x.t} className="flex items-center gap-1.5">
            <span className="text-brand-300">{x.icon}</span>
            {x.t}
          </span>
        ))}
      </div>
    </div>
  );
}

/* ── The animated showcase "screen" per product. ── */
function ProductScreen({ product }: { product: ProductId }) {
  if (product === "game") return <GameControlPanel />;
  if (product === "email") return <MailInbox />;
  // VPS + Hosting both read well as a live infra-monitoring panel.
  return <ServerDashboard />;
}

/* ── One plan card ── */
function PlanCard({
  plan, months, annualPct, accent,
}: { plan: ExplorerPlan; months: number; annualPct: number; accent: Accent }) {
  const { perMo, total, savingOverTerm } = priceFor(plan.monthlyCents, months, annualPct);
  const popular = plan.badge === "popular";
  const best = plan.badge === "best";
  const short = (VPS_TERMS.find((t) => t.months === months) ?? PRODUCT_TERMS[0]).short;

  return (
    <div
      className={`card lift group relative flex h-full flex-col ${
        popular ? accent.popRing : best ? "border-accent-cyan/40 ring-1 ring-accent-cyan/25" : ""
      }`}
      style={popular ? { boxShadow: `0 18px 50px -20px ${accent.popGlow}` } : undefined}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="font-semibold text-white">{plan.name}</span>
        {popular && (
          <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider ${accent.popBadge}`}>
            Most popular
          </span>
        )}
        {best && (
          <span className="rounded-full border border-accent-cyan/40 bg-accent-cyan/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-accent-cyan">
            Best value
          </span>
        )}
      </div>

      {/* Re-keyed on term change → the number visibly pops. */}
      <div key={months} className="motion-safe:animate-price-pop mt-3">
        <span className="text-4xl font-black tracking-tight text-white">{money(perMo)}</span>
        <span className="text-sm font-normal text-slate-400">/mo</span>
      </div>
      <p className="mt-1 h-4 text-[11px] text-slate-500">
        {months > 1
          ? `${money(total)} billed every ${short}${savingOverTerm > 0 ? ` · save ${money(savingOverTerm)}` : ""}`
          : "Billed monthly"}
      </p>

      <div className="mt-4 space-y-2 border-t border-white/[0.05] pt-4">
        {plan.specs.map((s) => (
          <div key={s.label} className="flex items-center justify-between text-sm">
            <span className="text-slate-400">{s.label}</span>
            <span className="font-mono font-semibold text-slate-200">{s.value}</span>
          </div>
        ))}
      </div>

      <Link
        href={plan.href}
        className={`btn-primary mt-5 w-full text-center ${popular ? accent.cta : ""}`}
      >
        Deploy Now
      </Link>
    </div>
  );
}

/* ── VPS add-on builder — live "your build" total from the SAME add-on maths
   checkout bills (extraDiskCentsAt for storage, the admin-resolved Plus price for
   daily backups). Add-ons are recurring monthly, labelled as on top of the plan. ── */
function AddOnBuilder({
  plans, months, annualPct, backupPlusCents, perGbCents, accent,
}: {
  plans: ExplorerPlan[];
  months: number;
  annualPct: number;
  backupPlusCents: number;
  perGbCents: number;
  accent: Accent;
}) {
  const defaultPlan = plans.find((p) => p.badge === "popular") ?? plans[0];
  const [planId, setPlanId] = useState<string>(defaultPlan?.id ?? "");
  const [extraGB, setExtraGB] = useState<number>(0);
  const [backup, setBackup] = useState<boolean>(false);

  const plan = plans.find((p) => p.id === planId) ?? defaultPlan;
  if (!plan) return null;

  const basePerMo = vpsEffectiveMonthly(plan.monthlyCents, months, annualPct);
  const storageMo = extraDiskCentsAt(extraGB, perGbCents); // exact charged maths
  const backupMo = backup ? backupPlusCents : 0;
  const totalMo = basePerMo + storageMo + backupMo;

  return (
    <div className="card relative flex h-full flex-col">
      <div className="flex items-center gap-2">
        <span className={`flex h-8 w-8 items-center justify-center rounded-lg border border-white/[0.08] bg-white/[0.03] ${accent.readoutText}`}>
          <IconGauge size={16} />
        </span>
        <div>
          <p className="font-semibold text-white">Build your server</p>
          <p className="text-[11px] text-slate-500">Add-ons bill monthly, on top of the plan.</p>
        </div>
      </div>

      {/* Base plan chooser */}
      <div className="mt-4 flex flex-wrap gap-1.5">
        {plans.map((p) => {
          const active = p.id === plan.id;
          return (
            <button
              key={p.id}
              onClick={() => setPlanId(p.id)}
              className={`rounded-lg border px-2.5 py-1 text-xs font-medium transition-colors ${
                active ? `${accent.gamePill} text-white` : "border-white/[0.08] bg-white/[0.02] text-slate-400 hover:text-slate-200"
              }`}
            >
              {p.name}
            </button>
          );
        })}
      </div>

      {/* Extra storage slider */}
      <div className="mt-5">
        <div className="flex items-center justify-between text-sm">
          <span className="flex items-center gap-1.5 text-slate-300"><IconDisk size={14} /> Extra storage</span>
          <span className="font-mono text-slate-200">
            +{extraGB} GB
            <span className="ml-1 text-[11px] text-slate-500">{storageMo > 0 ? `+${money(storageMo)}/mo` : "included"}</span>
          </span>
        </div>
        <input
          type="range"
          min={0}
          max={200}
          step={EXTRA_DISK_STEP_GB}
          value={extraGB}
          onChange={(e) => setExtraGB(Number(e.target.value))}
          aria-label="Extra storage in GB"
          className="mt-2 w-full accent-brand-500"
        />
        <p className="mt-0.5 text-[10px] text-slate-500">Priced at {money(perGbCents)}/GB / month · added storage is permanent.</p>
      </div>

      {/* Daily backups (Plus) toggle */}
      <button
        onClick={() => setBackup((v) => !v)}
        aria-pressed={backup}
        className="mt-4 flex items-center justify-between gap-3 rounded-xl border border-white/[0.08] bg-white/[0.02] px-3.5 py-3 text-left transition-colors hover:border-white/20"
      >
        <span className="flex items-center gap-2">
          <IconBackup size={16} className="text-slate-300" />
          <span>
            <span className="block text-sm font-medium text-white">Daily backups</span>
            <span className="block text-[11px] text-slate-500">Plus — keep 7 daily restore points · +{money(backupPlusCents)}/mo</span>
          </span>
        </span>
        <span
          className={`relative h-5 w-9 shrink-0 rounded-full transition-colors ${backup ? `bg-gradient-to-r ${accent.thumb}` : "bg-white/10"}`}
        >
          <span className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${backup ? "left-[18px]" : "left-0.5"}`} />
        </span>
      </button>

      {/* Live "your build" total */}
      <div key={`${plan.id}-${months}-${extraGB}-${backup}`} className={`motion-safe:animate-price-pop mt-5 rounded-xl border px-4 py-3 ${accent.readoutBox}`}>
        <div className="flex items-baseline justify-between">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-400">Your build</span>
          <span className="text-2xl font-black text-white">{money(totalMo)}<span className="text-sm font-normal text-slate-400">/mo</span></span>
        </div>
        <div className="mt-2 space-y-1 text-[11px] text-slate-500">
          <div className="flex justify-between"><span>{plan.name} plan</span><span className="font-mono">{money(basePerMo)}/mo</span></div>
          {storageMo > 0 && <div className="flex justify-between"><span>+{extraGB} GB storage</span><span className="font-mono">{money(storageMo)}/mo</span></div>}
          {backupMo > 0 && <div className="flex justify-between"><span>Daily backups (Plus)</span><span className="font-mono">{money(backupMo)}/mo</span></div>}
        </div>
      </div>

      <Link href={plan.href} className={`btn-primary mt-4 w-full text-center ${accent.cta}`}>Deploy this build</Link>
    </div>
  );
}

/* ── Domains: live search widget + TLD "indicative" grid ── */
function DomainsPanel({ tlds, href, accent }: { tlds: ExplorerTld[]; href: string; accent: Accent }) {
  return (
    <>
      <div className="mb-6">
        <DomainChecker compact />
      </div>
      <p className="section-label mb-3">Popular extensions</p>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
        {tlds.map((t) => (
          <div
            key={t.tld}
            className="group flex items-center justify-between rounded-2xl border border-white/[0.06] bg-navy-900/60 px-4 py-3 backdrop-blur-md transition-all duration-200 hover:-translate-y-0.5 hover:border-indigo-400/30 hover:bg-navy-850/70"
          >
            <span className="font-mono text-base font-bold text-white">{t.tld}</span>
            <span className="text-right text-xs">
              <span className="text-slate-500">from </span>
              <span className={`font-semibold ${accent.readoutText}`}>{money(t.fromCents)}/yr</span>
            </span>
          </div>
        ))}
      </div>
      <p className="mt-4 text-center text-xs text-slate-500">
        Indicative starting prices per year — premium names are priced individually. Search above for the exact live figure.{" "}
        <Link href={href} className="text-brand-300 hover:underline">Open domain search →</Link>
      </p>
    </>
  );
}

